#!/usr/bin/env python3
"""board.json (from dump_board.gd) -> board.h for tower.c."""
import json
import os

here = os.path.dirname(os.path.abspath(__file__))
d = json.load(open(os.path.join(here, "board.json")))
P = d["points"]


def rows(key):
    return ",".join("{" + ",".join(str(x) for x in p[key] + [-1] * (8 - len(p[key]))) + "}" for p in P)


out = [
    "// Generated by make_header.py from HuntBoards.komikan_matus(). Don't edit.",
    f"#define NP {len(P)}",
    "static const double RANK[NP]={" + ",".join(str(p["rank"]) for p in P) + "};",
    "static const int NADJ[NP]={" + ",".join(str(len(p["adj"])) for p in P) + "};",
    "static const int ADJ[NP][8]={" + rows("adj") + "};",
    "static const int NJ[NP]={" + ",".join(str(len(p["over"])) for p in P) + "};",
    "static const int OVER[NP][8]={" + rows("over") + "};",
    "static const int LAND[NP][8]={" + rows("land") + "};",
    f"static const int HSTART={d['hunter'][0]};",
    "static const int PREY[12]={" + ",".join(map(str, d["prey"])) + "};",
]
open(os.path.join(here, "board.h"), "w").write("\n".join(out) + "\n")
print("wrote board.h")
